def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell value can be collected at most once, even if both paths pass through it.
    """
    if N <= 0:
        return 0

    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Special case: single cell grid
    if N == 1:
        return grid[1][1]

    # Initialize DP arrays
    NEG_INF = -10**18
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over all possible sums of coordinates (k = i + j)
    for k in range(3, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue

                best_prev = NEG_INF
                # Four possible previous moves for each path
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val > best_prev:
                            best_prev = prev_val

                if best_prev == NEG_INF:
                    continue

                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_cur[i1][i2] = best_prev + add

        dp_prev = dp_cur

    result = dp_prev[N][N]
    return result if result != NEG_INF else 0

def cantor_numbering(N: int) -> str:
    """
    Determines the numerator and denominator of the N-th term in the Cantor table
    (enumeration of positive rational numbers in lowest terms along diagonals).

    Args:
        N (int): The position in the Cantor table to find the corresponding fraction for.

    Returns:
        str: A string representation of the fraction at the N-th position in the Cantor table.
    """
    if N <= 0:
        raise ValueError("N must be a positive integer")

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    diagonal = 2  # sum of numerator and denominator
    while True:
        for numerator in range(1, diagonal):
            denominator = diagonal - numerator
            if _gcd(numerator, denominator) == 1:
                count += 1
                if count == N:
                    return f"{numerator}/{denominator}"
        diagonal += 1

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if not coeffs:
        return "0"

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = "-" if coeff < 0 else ""
        else:
            sign = "-" if coeff < 0 else "+"

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ""
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f"x^{degree}"
        elif degree == 1:
            var_str = "x"
        else:
            var_str = ""

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return "0"

    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation: lengths must match
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse_mapping = {}

    for e_char, o_char in zip(encoded, original):
        # Ensure characters are uppercase letters
        if not ('A' <= e_char <= 'Z') or not ('A' <= o_char <= 'Z'):
            return "Failed"

        # Check forward mapping consistency
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char

        # Check reverse mapping consistency
        if o_char in reverse_mapping:
            if reverse_mapping[o_char] != e_char:
                return "Failed"
        else:
            reverse_mapping[o_char] = e_char

    # Mapping must cover all

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.

    Raises:
        ValueError: If the input is not a list of 3-element tuples of integers.
    """
    if not isinstance(student_scores, list):
        raise ValueError("Input must be a list.")
    for idx, item in enumerate(student_scores):
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError(f"Item at index {idx} is not a 3-element tuple.")
        if not all(isinstance(x, int) for x in item):
            raise ValueError(f"All elements in tuple at index {idx} must be integers.")
    # Use sorted with a key that enforces the required ordering
    return sorted(
        student_scores,
        key=lambda x: (-x[1], -x[2], x[0])
    )
